import org.apache.commons.lang3.math.NumberUtils;
import java.math.BigDecimal;
import java.math.BigInteger;

public class Probe {
    static void show(String s) {
        try {
            Number n = NumberUtils.createNumber(s);
            System.out.println(s + " -> " + (n==null?"null":n.getClass().getSimpleName()+" "+n));
        } catch (Exception e) {
            System.out.println(s + " -> EXC " + e.getClass().getSimpleName() + ": " + e.getMessage());
        }
    }
    public static void main(String[] args) {
        String[] tests = {
            "0x10", "0x7fffffff", "0x80000000", "0xFFFFFFFFL", "0xFFFFFFFFFFFFFFFFL",
            "010", "089", "00", "0", "3.0", "3.3", "3.5F", "3.5D", "100L",
            "123456789012345678901234567890L", "1.2e-5", "1e10", "NaN", "Infinity",
            "+Infinity", "-Infinity", "--1", "1.1.1", ".", ".D", ".e0", "09",
            "2.345", "2.355", "1.0f", "1.0d", "-0x10", "+0x10", "#1A", "-#1A",
            "1e400", "1.0e400", "1.0e400f", "1.0e400d"
        };
        for (String t : tests) show(t);
        System.out.println("isCreatable null: " + NumberUtils.isCreatable(null));
        System.out.println("isCreatable empty: " + NumberUtils.isCreatable(""));
        System.out.println("isParsable null: " + NumberUtils.isParsable(null));
        System.out.println("isParsable empty: " + NumberUtils.isParsable(""));
        System.out.println("isParsable NaN: " + NumberUtils.isParsable("NaN"));
        System.out.println("isParsable Infinity: " + NumberUtils.isParsable("Infinity"));
        System.out.println("isParsable 07: " + NumberUtils.isParsable("07"));
        System.out.println("isParsable 1.2.3: " + NumberUtils.isParsable("1.2.3"));
        System.out.println("isDigits null: " + NumberUtils.isDigits(null));
        System.out.println("isDigits empty: " + NumberUtils.isDigits(""));
        System.out.println("isDigits -1: " + NumberUtils.isDigits("-1"));
        BigDecimal b1 = new BigDecimal("2.345");
        System.out.println("scaled 2.345: " + NumberUtils.toScaledBigDecimal(b1));
        BigDecimal b2 = new BigDecimal("2.355");
        System.out.println("scaled 2.355: " + NumberUtils.toScaledBigDecimal(b2));
        System.out.println("scaled null: " + NumberUtils.toScaledBigDecimal((BigDecimal)null));
        try {
            System.out.println("createBigInteger -- : " + NumberUtils.createBigInteger("--1"));
        } catch (Exception e) { System.out.println("createBigInteger -- EXC " + e); }
        try {
            System.out.println("createInteger 089: " + NumberUtils.createInteger("089"));
        } catch (Exception e) { System.out.println("createInteger 089 EXC " + e); }
    }
}
EOF
